/**
 * Event tracking — from the apply-event-tracking skill (template v3).
 *
 * The ONLY module that talks to OpenPanel: every event goes through the typed
 * functions below. Framework-agnostic: it reads no environment variables; the
 * app passes its config in (see the skill's references/stacks.md). JavaScript
 * apps use the copy generated by to-js.mjs.
 *
 * Per dashboard, edit ONLY the controlled vocabulary (REPORTS, ENTITY_TYPES,
 * EXPORT_FORMATS, FEATURES), filled from its routes, tables and actions.
 */
import { OpenPanel } from '@openpanel/web';

/**
 * The company's self-hosted OpenPanel. Without apiUrl the SDK silently sends
 * events to OpenPanel Cloud. If the app sets a Content-Security-Policy, this
 * host must be in connect-src, or the browser blocks every event.
 */
const OPENPANEL_API_URL = 'https://openpanel.pti-cosmetics.com/api';

// ---- Controlled vocabulary: fill per dashboard ----------------------------
/** One per dashboard section/route, and per in-page panel (trackReportViewed). */
export const REPORTS = [
  'dashboard_strategic',
  'dashboard_tactical',
  'lead_time',
  'monitor',
  'settings',
] as const;
/** One per clickable table entity that opens a detail view. */
export const ENTITY_TYPES = [] as const;
/** The export formats this dashboard offers. */
export const EXPORT_FORMATS = [] as const;
/** Other deliberate actions worth counting (feature_used). */
export const FEATURES = [
  'ai_summary_opened',
  'ai_risks_opened',
  'chat_opened',
  'notification_settings_saved',
] as const;

export type Report = (typeof REPORTS)[number];
export type EntityType = (typeof ENTITY_TYPES)[number];
export type ExportFormat = (typeof EXPORT_FORMATS)[number];
export type Feature = (typeof FEATURES)[number];
export type FilterTrigger = 'apply' | 'reset';

/** Checked at runtime too, so a JavaScript app (no type check) cannot fragment them. */
const VOCAB: Record<string, readonly string[]> = {
  report: REPORTS, entity_type: ENTITY_TYPES, format: EXPORT_FORMATS, feature: FEATURES,
};
const SCROLL_THRESHOLDS = [25, 50, 75, 100] as const;

/**
 * The signed-in user, from the SSO (Microsoft Entra ID).
 * id = the stable object ID (MSAL account.localAccountId / claim `oid`), never the email.
 * email, name: from the SSO account. Identity lives ONLY here, never in event properties.
 * properties: role, division, squad, if the auth system has them.
 */
type User = {
  id: string;
  email?: string;
  name?: string;
  /** Only these keys. Never token claims, the account object or tokens. */
  properties?: Partial<Record<'role' | 'division' | 'squad', string>>;
};

let op: OpenPanel | null = null;
let lastPagePath: string | undefined;

/**
 * One page view per PATH. The SDK fires screen_view on any href change, so a tab
 * or filter kept in the query string (?tab=cards) would count as a new page view
 * on every change, on top of its own report_viewed / filter_applied.
 */
function onePageViewPerPath(event: { type: string; payload?: unknown }): boolean {
  const track = event.payload as { name?: string; properties?: Record<string, unknown> } | undefined;
  if (event.type !== 'track' || !track?.properties?.__path) return true;
  const url = new URL(String(track.properties.__path), 'http://x');
  // The SDK copies the current URL into EVERY event. Custom events get it without the
  // query string, so a term in the URL cannot ride along on a { sensitive: true } search.
  if (track.name !== 'screen_view') { track.properties.__path = url.origin + url.pathname; return true; }
  if (url.pathname === lastPagePath) return false;
  lastPagePath = url.pathname;
  return true;
}

/**
 * Call once, in the browser, at startup. With SSO: only AFTER the login redirect
 * is handled and any session-expiry check has run (the first screen_view records
 * the full URL, which before that still holds the authorization code), and pass
 * the signed-in user, so the landing page view is attributed to them.
 *
 * clientId empty or missing = tracking off, the app is unaffected. Checked for
 * truthiness on purpose: CI passes an EMPTY value when a variable is missing.
 * Staging and production are separate OpenPanel projects (separate client IDs),
 * so no environment property is needed.
 */
export function startAnalytics(options: { clientId?: string | null; user?: User | null }): void {
  if (typeof window === 'undefined') return; // server-side rendering (Next.js): nothing to track
  if (!options.clientId || op) return;
  // Never inside an iframe (MSAL silent token renewal loads the app there)
  // or on a page that is itself an OAuth response (MSAL popup).
  if (window.self !== window.top) return;
  if (/[?#&]state=/.test(window.location.href) && /[?#&](code|error)=/.test(window.location.href)) return;
  op = new OpenPanel({
    apiUrl: OPENPANEL_API_URL,
    clientId: options.clientId,
    trackScreenViews: true,   // every route change, incl. SPA navigation. Never call screenView() yourself.
    trackOutgoingLinks: true, // clicks on <a> to other hosts -> link_out (sends the link text)
    trackAttributes: false,   // off: it would send EVERY data-* attribute of a clicked element
    filter: onePageViewPerPath,
  });
  // Dashboards are layout-sensitive: which screen sizes do people really use?
  op.setGlobalProperties({ viewport: `${window.innerWidth}x${window.innerHeight}` });
  if (options.user) identifyUser(options.user); // synchronous, before the SDK's first screen_view fires
}

/** With SSO: call when a user signs in during the visit. */
export function identifyUser(user: User): void {
  if (!op) return;
  void op.identify({ profileId: user.id, email: user.email, firstName: user.name, properties: user.properties });
}

/** All custom events go through here: drops values outside the vocabulary. */
function send(name: string, props: Record<string, unknown>): void {
  if (!op) return;
  for (const [key, allowed] of Object.entries(VOCAB)) {
    const value = props[key];
    if (value !== undefined && !allowed.includes(String(value))) {
      console.warn(`[analytics] ${key}="${String(value)}" is not in the vocabulary, ${name} not sent`);
      return;
    }
  }
  // Codes, not text: an error message or a sentence here would leak whatever it contains.
  for (const key of ['error_type', 'search_box'] as const) {
    if (props[key] !== undefined && !/^[a-z0-9_]{1,40}$/.test(String(props[key]))) {
      console.warn(`[analytics] ${key} must be a short snake_case code, ${name} not sent`);
      return;
    }
  }
  void op.track(name, props);
}

// ---- The events ------------------------------------------------------------
// Call from an event handler (onClick, onSubmit), from the then/catch of an async
// call, or from a useEffect keyed on the one value that changed. Never from a
// component body or an effect that runs on every render.

/** After an interactive login completes (not on a silent session resume). */
export function trackUserLoggedIn(): void {
  send('user_logged_in', {});
}

/**
 * Before logout. AWAIT it, then log out: the SDK starts its request
 * asynchronously, so a logout that reloads at once would drop the event.
 * Capped at 1 s and never throws, so logout cannot hang on it.
 */
export async function trackUserLoggedOut(): Promise<void> {
  if (!op) return;
  const sent = op.track('user_logged_out', {}).catch(() => undefined);
  await Promise.race([sent, new Promise(resolve => setTimeout(resolve, 1000))]);
  op.clear();
}

/**
 * Filter keys that would collide with the event's own properties, the vocabulary check,
 * or the SDK (`groups`; `profileId` is caught by the snake_case rule).
 */
const RESERVED_FILTER_KEYS = ['report', 'trigger', 'entity_type', 'format', 'feature', 'groups'] as const;

/**
 * A filter takes effect: Apply or Reset (or an instant control such as a chip).
 * filters = ALL active filter values of that report, flat, not just the changed one:
 * build the object explicitly, snake_case keys, string or number values (a multi-select
 * as codes joined with ','). Values from data about people or customers: 'selected'.
 * A key from RESERVED_FILTER_KEYS (e.g. a store-format filter named `format`) must be
 * renamed (`store_format`): the event is dropped otherwise.
 */
export function trackFilterApplied(
  report: Report,
  trigger: FilterTrigger,
  filters: Record<string, string | number> & { [K in (typeof RESERVED_FILTER_KEYS)[number]]?: never },
): void {
  const bad = RESERVED_FILTER_KEYS.find(key => key in filters)
    ?? Object.entries(filters).find(([key, value]) =>
      !/^[a-z][a-z0-9_]*$/.test(key) || String(value).includes('@') || String(value).length > 300)?.[0];
  if (bad) {
    console.warn(`[analytics] filter "${bad}": reserved key, not snake_case, or a value that looks like an email or free text; filter_applied not sent`);
    return;
  }
  send('filter_applied', { ...filters, report, trigger });
}

/** An in-page tab or panel switch. A report that is its own route is already a screen_view. */
export function trackReportViewed(report: Report): void {
  send('report_viewed', { report });
}

/** A table row opens a detail view in the page (popup, drawer). Catalog/business entity IDs only. */
export function trackDetailOpened({ report, entity_type, entity_id }: { report: Report; entity_type: EntityType; entity_id?: string }): void {
  // Fields taken one by one: a spread table row cannot carry its other columns along.
  // entity_id: omit it when the row is a person, customer, employee or transaction.
  send('detail_opened', { report, entity_type, ...(entity_id === undefined ? {} : { entity_id }) });
}

/** Any export or download. One event, the format as a property. */
export function trackReportExported({ report, format }: { report: Report; format: ExportFormat }): void {
  send('report_exported', { report, format });
}

/** The user hits a failure: an error message, or a failed load that leaves an empty view or an endless spinner. */
export function trackErrorShown({ report, error_type }: { report: Report; error_type: string }): void {
  send('error_shown', { report, error_type });
}

/** Any other deliberate action worth counting; add the value to FEATURES first. */
export function trackFeatureUsed({ report, feature }: { report: Report; feature: Feature }): void {
  send('feature_used', { report, feature });
}

/** Only for window.open(); <a> clicks are tracked automatically under the same name. */
export function trackLinkOut(href: string, text?: string): void {
  send('link_out', { href, text });
}

// ---- Search (debounced) -----------------------------------------------------
const SEARCH_SETTLE_MS = 1000;
const searchTimers = new Map<string, ReturnType<typeof setTimeout>>();
const lastSearch = new Map<string, string>();

/**
 * Sends ONE `search` event per search box, 1 s after the term stops changing,
 * and only if the term changed. searchBox must be UNIQUE per box: the debounce
 * is per box, so two boxes sharing one cancel each other. Call it from a
 * useEffect keyed on the term AND the result count, AFTER the results exist.
 *
 * resultsCount: a number; `undefined` = still loading (nothing is sent until a
 * call with the count arrives, so a slow search keeps its count); `null` = this
 * box has no count (sent without one).
 * sensitive: REQUIRED decision. true when the box can match people, customers,
 * stores or transactions: the term is not sent, only its length and the count.
 * Missing (a JavaScript app) is treated as sensitive.
 */
export function trackSearch(
  searchTerm: string,
  report: Report,
  searchBox: string,
  resultsCount: number | null | undefined,
  options: { sensitive: boolean },
): void {
  const term = searchTerm.trim().toLowerCase().slice(0, 100);
  clearTimeout(searchTimers.get(searchBox));
  if (term.length < 2) {
    lastSearch.delete(searchBox); // cleared box: the same term again later is a new search
    return;
  }
  if (resultsCount === undefined) return; // still loading: the call with the count will send
  const sensitive = options?.sensitive !== false;
  searchTimers.set(searchBox, setTimeout(() => {
    if (lastSearch.get(searchBox) === term || !op) return;
    lastSearch.set(searchBox, term);
    send('search', {
      report,
      search_box: searchBox,
      ...(sensitive ? {} : { search_term: term }),
      search_term_length: term.length,
      ...(resultsCount === null ? {} : { results_count: resultsCount }),
    });
  }, SEARCH_SETTLE_MS));
}

// ---- Scroll depth -----------------------------------------------------------
let scrollTrackingStarted = false;

/**
 * scroll_depth when 25/50/75/100 % of the content has been in view, each at most
 * once per page view (resets when the path changes). Call once, any time after
 * startAnalytics; further calls do nothing. getReport maps the current location
 * to a report (undefined = not tracked).
 * getContainer: only when the page itself does not scroll but a layout element
 * does (an overflow:auto main area); it is looked up on every scroll, so the
 * element may mount later or be re-mounted.
 * Pages with nothing to scroll send no scroll_depth at all.
 */
export function startScrollTracking(getReport: () => Report | undefined, getContainer?: () => Element | null): void {
  if (typeof window === 'undefined' || scrollTrackingStarted) return;
  scrollTrackingStarted = true;
  const fired = new Set<number>();
  let path = window.location.pathname;
  // scroll does not bubble; a capturing listener on document sees every scroller.
  document.addEventListener('scroll', event => {
    const scroller = event.target === document ? document.documentElement : event.target;
    const page = getContainer ? getContainer() : document.documentElement;
    if (!(scroller instanceof Element) || scroller !== page) return; // a dropdown or table, not the page
    if (window.location.pathname !== path) { path = window.location.pathname; fired.clear(); }
    // Nothing to scroll (a short page, or a loading state right after a route change, where
    // the browser clamps the old scroll position and fires a scroll event): not a depth.
    // Counting it as 100 % would spend every threshold before the content exists.
    if (scroller.scrollHeight <= scroller.clientHeight + 1) return;
    const seen = Math.min(100, ((scroller.scrollTop + scroller.clientHeight + 1) / scroller.scrollHeight) * 100); // +1 px: sub-pixel bottoms
    const report = getReport();
    if (!report) return;
    for (const threshold of SCROLL_THRESHOLDS) {
      if (seen >= threshold && !fired.has(threshold)) {
        fired.add(threshold);
        send('scroll_depth', { report, threshold });
      }
    }
  }, { capture: true, passive: true });
}
